var connectSticks = function(sticks) {
    // Simple min-heap simulation or sorting
    sticks.sort((a, b) => a - b);
    let totalCost = 0;
    while (sticks.length > 1) {
        const cost = sticks.shift() + sticks.shift();
        totalCost += cost;
        // insert cost keeping sorted
        let idx = 0;
        while (idx < sticks.length && sticks[idx] < cost) idx++;
        sticks.splice(idx, 0, cost);
    }
    return totalCost;
};

