class Solution {
public:
    int connectSticks(vector<int>& sticks) {
        priority_queue<int, vector<int>, greater<int>> minHeap(sticks.begin(), sticks.end());
        int totalCost = 0;
        while (minHeap.size() > 1) {
            int x = minHeap.top(); minHeap.pop();
            int y = minHeap.top(); minHeap.pop();
            totalCost += x + y;
            minHeap.push(x + y);
        }
        return totalCost;
    }
};

